import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Instant Fire', () => {
  test('Component renders without firing alert', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el) throw new Error('Component did not render');
if (!el.textContent.includes('0')) throw new Error('Should show count 0');
  });

  test('Increment button works', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#increment').click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('1')) throw new Error('Count should be 1');
  });

  test('Alert fires on click, not on render', async () => {
    const { container: root } = render(<App />);
    const calls = [];
const origAlert = window.alert;
window.alert = (msg) => { calls.push(String(msg)); };
try {
  const inc = root.querySelector('#increment');
  if (inc) { inc.click(); await tick(); }
  if (calls.length > 0) throw new Error('Alert fired during render — pass the function reference, not the result of calling it');
  const btn = root.querySelector('#alert-btn');
  if (!btn) throw new Error('No #alert-btn found');
  btn.click();
  await tick();
  if (calls.length === 0) throw new Error('Clicking #alert-btn did nothing — onClick should be a function reference');
  if (!calls[calls.length - 1].includes('Count is:')) throw new Error('Alert message should include "Count is:"');
} finally {
  window.alert = origAlert;
}
  });
});
